@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var status = stepIndex == CurrentStep ? "active"
                   : stepIndex < CurrentStep ? "completed"
                   : "future";

        <div class="step @status" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (status == "completed")
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>

        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    cursor: default;
    min-width: 5rem;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #d1d5db;
    background: #fff;
    color: #9ca3af;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

.step-label {
    font-size: 0.75rem;
    color: #9ca3af;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step.completed .step-label {
    color: #16a34a;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    margin: 0 0.25rem;
    margin-bottom: 1.4rem;
    min-width: 2rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #16a34a;
}

.work-entry-card {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.card-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #374151;
}

.btn-remove {
    background: none;
    border: 1px solid #ef4444;
    color: #ef4444;
    padding: 0.25rem 0.75rem;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-remove:hover {
    background: #fef2f2;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.form-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 0.75rem;
}

.form-group label {
    font-size: 0.85rem;
    font-weight: 500;
    color: #374151;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="date"],
.form-group textarea {
    padding: 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

.checkbox-label {
    flex-direction: row !important;
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.35rem;
    font-weight: 400 !important;
    font-size: 0.8rem !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

