toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    cursor: default;
    min-width: 5rem;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #d1d5db;
    background: #fff;
    color: #9ca3af;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #2563eb;
    background: #2563eb;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #16a34a;
    background: #16a34a;
    color: #fff;
}

.step-label {
    font-size: 0.75rem;
    color: #9ca3af;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step.completed .step-label {
    color: #16a34a;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    margin: 0 0.25rem;
    margin-bottom: 1.4rem;
    min-width: 2rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #16a34a;
}

