@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply
@using sv_cb35ddee116d4e4290f8476496e7150a.Models

<h3>Personal Information</h3>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-error">@ErrorMessage</div>
}

<div class="form-group">
    <label>Full Name *</label>
    <input type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="Your full name" />
</div>

<div class="form-group">
    <label>Email Address *</label>
    <input type="email" @bind="Model.Email" @bind:event="oninput" placeholder="email@example.com" />
    @if (IsValidatingEmail)
    {
        <span class="hint">Validating email...</span>
    }
</div>

<div class="form-group">
    <label>Phone Number *</label>
    <input type="text" @bind="Model.Phone" @bind:event="oninput" placeholder="Phone number" />
</div>

<div class="form-group">
    <label>Address *</label>
    <textarea rows="2" @bind="Model.Address" @bind:event="oninput" placeholder="Your address"></textarea>
</div>

<div class="step-actions">
    <div></div>
    <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (!Model.IsValid)
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidatingEmail = true;
            try
            {
                var isValid = await ValidateEmail(Model.Email);
                if (!isValid)
                {
                    ErrorMessage = "Please enter a valid email address.";
                    return;
                }
            }
            finally
            {
                IsValidatingEmail = false;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply
@using sv_cb35ddee116d4e4290f8476496e7150a.Models

<h3>Work History</h3>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-error">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryEditor Entry="Entries[index]"
                     Index="index"
                     CanRemove="Entries.Count > 1"
                     OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn-secondary" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="step-actions">
    <button class="btn-outline" @onclick="OnBack">Back</button>
    <button class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (!Entries.All(e => e.IsValid))
        {
            ErrorMessage = "Please fill in all required fields (company, title, start date) for each position.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

