        @CoverLetter.Length / @MaxLength characters
    </span>
</div>

<div class="step-actions">
    <button class="btn-outline" @onclick="OnBack">Back</button>
    <button class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;

    private async Task OnTextChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

.form-group textarea {
    width: 100%;
    resize: vertical;
    font-family: inherit;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #ef4444;
    font-weight: 600;
}

@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply
@using sv_cb35ddee116d4e4290f8476496e7150a.Models

<h3>Review &amp; Submit</h3>

@if (IsSubmitted)
{
    <div class="confirmation">
        <div class="confirmation-icon">&#10003;</div>
        <h4>Application Submitted Successfully!</h4>
        <p>Your application ID is <strong>#@ApplicationId</strong></p>
        <p>We'll be in touch soon. Thank you for applying!</p>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-error">@ErrorMessage</div>
    }

    <div class="review-section">
        <div class="section-header">
            <h4>Personal Information</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>Work History</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="work-summary">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="date-range">
                    @entry.StartDate?.ToString("MMM yyyy")
                    &ndash;
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="description">@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>References</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var reference in References)
        {
            <div class="reference-summary">
                <strong>@reference.Name</strong> — @reference.Relationship
                <br />
                <span>@reference.Email &middot; @reference.Phone</span>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h4>Cover Letter</h4>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-text">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
    </div>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int? ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        ErrorMessage = null;
        IsSubmitting = true;

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch
        {
            ErrorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1rem 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.section-header h4 {
    margin: 0;
