}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.85rem;
}

dd {
    margin: 0;
    font-size: 0.9rem;
    color: #1f2937;
}

.work-summary, .reference-summary {
    padding: 0.5rem 0;
    font-size: 0.9rem;
}

.work-summary + .work-summary,
