    border-top: 1px solid #e5e7eb;
}

.date-range {
    font-size: 0.8rem;
    color: #6b7280;
}

.description {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    color: #4b5563;
}

.cover-letter-text {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #374151;
    margin: 0;
}

.btn-submit {
    min-width: 10rem;
}

.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 4rem;
