    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.confirmation h4 {
    font-size: 1.25rem;
    color: #1f2937;
    margin-bottom: 0.5rem;
}

.confirmation p {
    color: #6b7280;
}

