@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply

<h3>Cover Letter</h3>

<div class="form-group">
    <label>Write your cover letter</label>
    <textarea rows="12" @bind="CoverLetter" @bind:event="oninput" @bind:after="OnTextChanged"
              maxlength="@MaxLength"
              placeholder="Tell us why you're a great fit for this position..."></textarea>
    <span class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
        @CoverLetter.Length / @MaxLength characters
    </span>
</div>

<div class="step-actions">
    <button class="btn-outline" @onclick="OnBack">Back</button>
    <button class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;

    private async Task OnTextChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

.form-group textarea {
    width: 100%;
    resize: vertical;
    font-family: inherit;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #ef4444;
    font-weight: 600;
}

