arguments.file_text:
@page "/apply"
@rendermode InteractiveServer

@namespace sv_cb35ddee116d4e4290f8476496e7150a.Components.Pages.Apply
@using sv_cb35ddee116d4e4290f8476496e7150a.Models
@using sv_cb35ddee116d4e4290f8476496e7150a.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   StepNames="_stepNames"
                   OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Model="_personalInfo"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="_references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 CoverLetterChanged="val => _coverLetter = val"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnEditSection="GoToStep"
                            OnBack="PreviousStep"
                            OnSubmit="SubmitAsync" />
                break;
        }
    </div>
</div>

@code {
    private static readonly IReadOnlyList<string> _stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep;
    private PersonalInfoModel _personalInfo = new();
    private List<WorkEntryModel> _workEntries = [new()];
    private List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    private void NextStep() => _currentStep = Math.Min(_currentStep + 1, _stepNames.Count - 1);
    private void PreviousStep() => _currentStep = Math.Max(_currentStep - 1, 0);
    private void GoToStep(int step) => _currentStep = Math.Clamp(step, 0, _stepNames.Count - 1);

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            _personalInfo.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 48rem;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-container h2 {
    text-align: center;
    color: #1f2937;
    margin-bottom: 1.5rem;
}

.step-content {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 0.75rem;
    padding: 1.5rem 2rem;
}

.step-content h3 {
    color: #1f2937;
    margin-top: 0;
    margin-bottom: 1.25rem;
    font-size: 1.2rem;
}

/* Shared form styles used by step components */
::deep .form-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 1rem;
}

::deep .form-group label {
    font-size: 0.85rem;
    font-weight: 500;
    color: #374151;
    margin-bottom: 0.3rem;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="date"],
::deep .form-group textarea {
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-family: inherit;
    width: 100%;
    box-sizing: border-box;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

::deep .hint {
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.2rem;
}

::deep .alert-error {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #b91c1c;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

::deep .step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e5e7eb;
}

::deep .btn-primary {
    background: #2563eb;
    color: #fff;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
}

::deep .btn-primary:hover {
    background: #1d4ed8;
}

::deep .btn-primary:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

::deep .btn-outline {
    background: #fff;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    cursor: pointer;
}

::deep .btn-outline:hover {
    background: #f9fafb;
}

::deep .btn-secondary {
    background: none;
    border: 1px dashed #d1d5db;
    color: #6b7280;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.85rem;
    width: 100%;
    margin-bottom: 0.5rem;
}

::deep .btn-secondary:hover {
    border-color: #2563eb;
    color: #2563eb;
}

